window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f28b41d34bcd9032"]={"versions": [{"id": "FIG-f28b41d34bcd9032", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungs- und Matrizendiagramm zum AUTOSAR Generic Structure Template (GST). Das Diagramm visualisiert die semantischen Regeln für das Zusammenführen (Merge / Splitable-Semantik) von Modellelementen mit eigener Identität (Identifiable / ShortName) und Variationspunkten (VariationPoint, VP), wenn diese in aggregierten Sammlungen mit Multiplizität größer eins (<code>multiplicity &gt; 1</code>) aus zwei Teilmodellen kombiniert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Partial Model 1 &amp; Partial Model 2</strong>: Eingangsmodelle mit instanziierten Elementen verschiedener Identitäten („A“, „B“, „C“, „Z“) und Bindung an Variationspunkte (VP1, VP2, VPn bzw. No VP).\n</li><li><strong>Matrixstruktur (Identität vs. Variationspunkt)</strong>:\n<ul class=\"fig-list\"><li>Zeilen: Identitäten (<code>ID „A“</code>, <code>ID „B“</code>, <code>ID „C“</code>, <code>ID „Z“</code>).\n</li><li>Spalten: Variationspunkte (<code>No VP</code>, <code>VP1</code>, <code>VP2</code>, <code>VPn</code>).\n</li></ul>\n</li><li><strong>Legende / Knotentypen</strong>:\n<ul class=\"fig-list\"><li>Blauer Kreis: Elemente aus Partial Model 1.\n</li><li>Gelber Kreis: Elemente aus Partial Model 2.\n</li><li>Roter Kreis (<code>Elements where the splits are merged</code>): Zusammenführung kongruenter Split-Elemente innerhalb desselben Matrixfeldes.\n</li><li>Roter Blitz: Konfliktfall / Fehlerzustand bei inkompatibler Zuordnung (z. B. ungleiche Variationspunkte bei gleicher Identität).\n</li></ul>\n</li><li><strong>Result: Collection with ...</strong>: Aggregiertes Gesamtergebnis der Kollektion nach Auswertung der Merge-Regeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beschreibt den paarweisen Abgleich und Merge von Modellelementen gleicher Identität und gleicher Variation:</p>\n<ol class=\"fig-list\"><li><strong>Identische ID und identischer VP (z. B. ID „A“ an VP1, ID „B“ ohne VP, ID „Z“ an VP2 und VPn)</strong>: Treffen zwei Elemente mit identischer ID und identischer Variationspunkt-Bindung aufeinander, werden sie im selben Slot zusammengeführt (Merge markiert durch rote Einkreisung).\n</li><li><strong>Identische ID bei disjunkter bzw. inkonsistenter VP-Zuordnung (z. B. ID „C“)</strong>: Ein Element aus Modell 1 ohne VP trifft auf ein Element aus Modell 2 an VP1. Da die Variationspunkt-Bindungen divergieren, entsteht ein Modellierungs- bzw. Merge-Konflikt (symbolisiert durch den roten Blitz).\n</li><li><strong>Ergebnisbildung</strong>: Die Kollektion im Zielmodell enthält die gemergten Elemente sowie die disjunkten, wohldefinierten Instanzen je Identität und Variationspunkt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung von AUTOSAR-Authoring-Tools und Modell-Merger-Werkzeugen:</p>\n<ul class=\"fig-list\"><li>Bei Aggregationen mit Multiplizität &gt; 1 bestimmt die Kombination aus Identität (<code>shortName</code>) und Variationspunkt-Bindung die Eindeutigkeit des Splitable-Merges.\n</li><li>Elemente mit identischem Bezeichner müssen auf denselben Variationspunkt verweisen, um als Split-Teile desselben Modellelements zusammengeführt werden zu können; divergierende Variationsbindungen für denselben Bezeichner stellen einen unzulässigen Konflikt dar.\n</li></ul>"}, {"id": "FIG-cf3c4c0b24c38e06", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungs- und Matrizendiagramm zum AUTOSAR Generic Structure Template (GST). Das Diagramm visualisiert die semantischen Regeln für das Zusammenführen (Merge / Splitable-Semantik) von Modellelementen mit eigener Identität (Identifiable / ShortName) und Variationspunkten (VariationPoint, VP), wenn diese in aggregierten Sammlungen mit Multiplizität größer eins (<code>multiplicity &gt; 1</code>) aus zwei Teilmodellen kombiniert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Partial Model 1 &amp; Partial Model 2</strong>: Eingangsmodelle mit instanziierten Elementen verschiedener Identitäten („A“, „B“, „C“, „Z“) und Bindung an Variationspunkte (VP1, VP2, VPn bzw. No VP).\n</li><li><strong>Matrixstruktur (Identität vs. Variationspunkt)</strong>:\n<ul class=\"fig-list\"><li>Zeilen: Identitäten (<code>ID „A“</code>, <code>ID „B“</code>, <code>ID „C“</code>, <code>ID „Z“</code>).\n</li><li>Spalten: Variationspunkte (<code>No VP</code>, <code>VP1</code>, <code>VP2</code>, <code>VPn</code>).\n</li></ul>\n</li><li><strong>Legende / Knotentypen</strong>:\n<ul class=\"fig-list\"><li>Blauer Kreis: Elemente aus Partial Model 1.\n</li><li>Gelber Kreis: Elemente aus Partial Model 2.\n</li><li>Roter Kreis (<code>Elements where the splits are merged</code>): Zusammenführung kongruenter Split-Elemente innerhalb desselben Matrixfeldes.\n</li><li>Roter Blitz: Konfliktfall / Fehlerzustand bei inkompatibler Zuordnung (z. B. ungleiche Variationspunkte bei gleicher Identität).\n</li></ul>\n</li><li><strong>Result: Collection with ...</strong>: Aggregiertes Gesamtergebnis der Kollektion nach Auswertung der Merge-Regeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beschreibt den paarweisen Abgleich und Merge von Modellelementen gleicher Identität und gleicher Variation:</p>\n<ol class=\"fig-list\"><li><strong>Identische ID und identischer VP (z. B. ID „A“ an VP1, ID „B“ ohne VP, ID „Z“ an VP2 und VPn)</strong>: Treffen zwei Elemente mit identischer ID und identischer Variationspunkt-Bindung aufeinander, werden sie im selben Slot zusammengeführt (Merge markiert durch rote Einkreisung).\n</li><li><strong>Identische ID bei disjunkter bzw. inkonsistenter VP-Zuordnung (z. B. ID „C“)</strong>: Ein Element aus Modell 1 ohne VP trifft auf ein Element aus Modell 2 an VP1. Da die Variationspunkt-Bindungen divergieren, entsteht ein Modellierungs- bzw. Merge-Konflikt (symbolisiert durch den roten Blitz).\n</li><li><strong>Ergebnisbildung</strong>: Die Kollektion im Zielmodell enthält die gemergten Elemente sowie die disjunkten, wohldefinierten Instanzen je Identität und Variationspunkt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung von AUTOSAR-Authoring-Tools und Modell-Merger-Werkzeugen:</p>\n<ul class=\"fig-list\"><li>Bei Aggregationen mit Multiplizität &gt; 1 bestimmt die Kombination aus Identität (<code>shortName</code>) und Variationspunkt-Bindung die Eindeutigkeit des Splitable-Merges.\n</li><li>Elemente mit identischem Bezeichner müssen auf denselben Variationspunkt verweisen, um als Split-Teile desselben Modellelements zusammengeführt werden zu können; divergierende Variationsbindungen für denselben Bezeichner stellen einen unzulässigen Konflikt dar.\n</li></ul>"}], "trans": [{"from": "FIG-f28b41d34bcd9032", "to": "FIG-cf3c4c0b24c38e06", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
